<?php
require dirname(__DIR__).'/app/bootstrap.php';
require_permission('settings.manage');
$error=''; $notice='';
$defaults=[
 'brand_name'=>'NOWRD','brand_mark'=>'n.','brand_tagline'=>'Less noise. More meaning.',
 'site_description'=>'An independent publishing space for ideas that deserve a little more time.','site_url'=>'',
 'editorial_mission'=>'An independent publishing space for ideas that deserve a little more time.',
 'editorial_guidelines'=>'Write with clarity. Be curious, specific, and fair. Prefer useful detail over noise. Credit sources and respect the reader’s time.',
 'default_author'=>'NOWRD Editors','dashboard_page_size'=>'20','default_excerpt_length'=>'150',
 'confirm_delete'=>'1','show_dashboard_welcome'=>'1'
];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $action=(string)($_POST['action']??'save');
 if($action==='export'){
  $all=$pdo->query('SELECT setting_key,setting_value FROM settings ORDER BY setting_key')->fetchAll(PDO::FETCH_KEY_PAIR);
  $export=['product'=>'NOWRD CMS','type'=>'settings-backup','exported_at'=>gmdate('c'),'note'=>'This file contains settings only; it does not include articles, media files, users, or database credentials.','settings'=>$all];
  header('Content-Type: application/json; charset=utf-8'); header('Content-Disposition: attachment; filename="nowrd-settings-backup-'.gmdate('Y-m-d').'.json"');
  echo json_encode($export,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit;
 }
 try {
  $values=[
   'brand_name'=>trim((string)($_POST['brand_name']??'')),
   'brand_mark'=>trim((string)($_POST['brand_mark']??'')),
   'brand_tagline'=>trim((string)($_POST['brand_tagline']??'')),
   'site_description'=>trim((string)($_POST['site_description']??'')),
   'site_url'=>rtrim(trim((string)($_POST['site_url']??'')),'/'),
   'editorial_mission'=>trim((string)($_POST['editorial_mission']??'')),
   'editorial_guidelines'=>trim((string)($_POST['editorial_guidelines']??'')),
   'default_author'=>trim((string)($_POST['default_author']??'')),
   'dashboard_page_size'=>(string)($_POST['dashboard_page_size']??'20'),
   'default_excerpt_length'=>(string)($_POST['default_excerpt_length']??'150'),
   'confirm_delete'=>isset($_POST['confirm_delete'])?'1':'0',
   'show_dashboard_welcome'=>isset($_POST['show_dashboard_welcome'])?'1':'0',
  ];
  if($values['brand_name']===''||text_length($values['brand_name'])>80) throw new RuntimeException('Nama brand wajib diisi dan maksimal 80 karakter.');
  if($values['brand_mark']===''||text_length($values['brand_mark'])>8) throw new RuntimeException('Mark/logo teks wajib diisi dan maksimal 8 karakter.');
  if(text_length($values['brand_tagline'])>180||text_length($values['site_description'])>320||text_length($values['editorial_mission'])>320||text_length($values['editorial_guidelines'])>1500||text_length($values['default_author'])>100) throw new RuntimeException('Ada teks yang melewati batas karakter. Periksa kembali isian.');
  if($values['site_url']!==''&&!filter_var($values['site_url'],FILTER_VALIDATE_URL)) throw new RuntimeException('URL situs harus berupa URL lengkap, misalnya https://domain.com.');
  if(!in_array($values['dashboard_page_size'],['10','20','30','50'],true)) throw new RuntimeException('Jumlah artikel per halaman tidak valid.');
  if(!in_array($values['default_excerpt_length'],['100','150','200','250'],true)) throw new RuntimeException('Panjang ringkasan bawaan tidak valid.');
  $q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');
  foreach($values as $key=>$value)$q->execute([$key,$value]);
  // Keep legacy/public theme keys in sync for older templates.
  $q->execute(['site_name',$values['brand_name']]); $q->execute(['site_tagline',$values['brand_tagline']]); cache_clear();
  nowrd_audit('settings.updated','settings',null,'Publication and workspace settings updated');
  $notice='Pengaturan tersimpan. Preferensi editorial dan workspace akan digunakan oleh dashboard.';
 } catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Pengaturan gagal disimpan. Periksa koneksi database.';if(!($ex instanceof RuntimeException))error_log('NOWRD settings error: '.$ex->getMessage());}
}
$values=[];foreach($defaults as $key=>$default)$values[$key]=setting($key,$default);
